print('note title:', note['title'])
print('meetings parsed:', len(meetings))
print(meetings)

weekday_map = {'Monday':0,'Tuesday':1,'Wednesday':2,'Thursday':3,'Friday':4,'Saturday':5,'Sunday':6}

def find_next_date_for_weekday(target_weekday, start_dt):
    for offset in range(0,7):
        d = (start_dt + timedelta(days=offset)).date()
        if d.weekday() == target_weekday:
            return datetime.combine(d, datetime.min.time())
    return None

week_meetings=[]
for mtg in meetings:
    tgt = weekday_map.get(mtg['day'])
    base_date_dt = find_next_date_for_weekday(tgt, cur_dt)
    if base_date_dt is None:
        continue
    hh, mm = mtg['time'].split(':')
    start_dt = base_date_dt.replace(hour=int(hh), minute=int(mm), second=0, microsecond=0)
    remind_dt = start_dt - timedelta(minutes=20)
    week_meetings.append({
        **mtg,
        'start_dt': start_dt,
        'remind_dt': remind_dt,
        'scheduled_send_at': remind_dt.strftime('%Y-%m-%d|%H:%M:%S')
    })

print('week_meetings:', len(week_meetings))
for m in week_meetings:
    print(m['meeting_name'], '->', m['start_dt'], 'remind', m['remind_dt'], 'recipients names:', m['attendees'])

# Resolve attendee names -> phone contacts (exact first_name match, handle ambiguity)
unique_names = sorted({n for m in week_meetings for n in m['attendees']})
print('unique attendee names:', unique_names)

resolved_name_to_contact=[]
name_to_email_candidates={}

for name in unique_names:
    # paginate search_contacts
    page_index=0
    page_limit=20
    all_results=[]
    while True:
        resp = apis.phone.search_contacts(access_token=token_phone['access_token'], query=name, page_index=page_index, page_limit=page_limit)
        if not resp:
            break
        all_results.extend(resp)
        page_index += 1
        if len(resp) < page_limit:
            # but still safe to continue until empty
            pass
    exact = [c for c in all_results if (c.get('first_name','').strip().lower()==name.strip().lower())]
    print('name:', name, 'search_results:', len(all_results), 'exact_first_name_matches:', len(exact))
    # if multiple, list candidates
    if len(exact)==1:
        name_to_email_candidates[name]=[exact[0].get('email')]
    else:
        name_to_email_candidates[name]=[e.get('email') for e in exact]
    resolved_name_to_contact.append((name, len(exact), [(c.get('first_name'), c.get('last_name'), c.get('email')) for c in exact[:10]]))

print('resolved_name_to_contact (preview):')
for row in resolved_name_to_contact:
    print(row[0], 'matches', row[1], 'candidates', row[2])

# If ambiguous (more than 1 match), exclude completely
ambiguous_names=[name for name,cands in name_to_email_candidates.items() if len([x for x in cands if x])!=1]
print('ambiguous_names:', ambiguous_names)

# For unambiguous names, map contact email -> gmail user email by exact email match
