    exact_users=[u for u in all_users if u.get('email','').strip().lower()==ce.strip().lower()]
    print('Mapping name', name, 'contact_email', ce, 'gmail_search_results', len(all_users), 'exact_email_matches', len(exact_users))
    if len(exact_users)==1:
